def solve_global_bbox(grid):
    h, w = len(grid), len(grid[0])
    non_zeros = [(i,j) for i in range(h) for j in range(w) if grid[i][j] != 0]

    if not non_zeros:
        return [row[:] for row in grid]

    min_r, max_r = min(c[0] for c in non_zeros), max(c[0] for c in non_zeros)
    mid_row = (min_r + max_r) // 2

    result = [row[:] for row in grid]
    for c in range(w):
        result[mid_row][c] = 3

    return result

